function daysBetween(from,to){var a=new Date(from+'T00:00:00');var b=new Date(to+'T00:00:00');return Math.round((b-a)/86400000);}
function plan(subjects,totalDays){if(!subjects.length||totalDays<1)return [];var out=[];for(var d=0;d<totalDays;d++){out.push({day:d+1,subject:subjects[d%subjects.length]});}return out;}
function countdown(target){var today=new Date();var t=new Date(target+'T00:00:00');return Math.round((t-today)/86400000);}
var EXPORTS={daysBetween:daysBetween,plan:plan,countdown:countdown};


function rngFactory(seed){ var s=(seed>>>0)||1; return function(){ s=(s*1664525+1013904223)>>>0; return s/4294967296; }; }

if (typeof module !== 'undefined' && module.exports) { module.exports = EXPORTS; }
if (typeof window !== 'undefined') { window.StudyPlanForgePure = EXPORTS; }
